/** Shape of the committed catalog seed (generated by scripts/build-catalog-seed.mjs). */

export interface SeedArtist {
  id: string;
  name: string;
  bio: string | null;
  art_url: string | null;
  is_verified: boolean;
  genres: string[];
  external_id: string;
}

export interface SeedAlbum {
  id: string;
  title: string;
  artist_id: string;
  type: 'album' | 'single' | 'ep';
  release_date: string | null;
  art_url: string | null;
  external_id: string;
}

export interface SeedTrack {
  id: string;
  title: string;
  artist_id: string;
  album_id: string;
  duration_ms: number;
  track_number: number;
  has_lyrics: boolean;
  play_count: number;
  genres: string[];
  explicit: boolean;
  external_id: string;
  art_url: string | null;
  lyrics: {
    lrc_text: string;
    offset_ms: number;
    synced: boolean;
  } | null;
}

export interface CatalogSeed {
  version: number;
  generated_from: string;
  generated_at: string;
  artists: SeedArtist[];
  albums: SeedAlbum[];
  tracks: SeedTrack[];
}
